INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72584, 'spa', 'Burlarse con desprecio', 'En Gálatas 6:7, Pablo pronuncia su solemne advertencia: no os engañéis, de Dios nadie se burla. La forma pasiva enfatiza que Dios no puede ser tratado con desprecio exitosamente. El contexto de siembra y cosecha subraya que tratar la ley moral de Dios con desprecio, sembrando para la carne, inevitablemente acarrea consecuencias conforme a la justicia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72585, 'spa', 'Piedra de molino', 'Lucas 17:2 emplea la piedra de molino en la severa advertencia de Jesús sobre causar tropiezo a los creyentes. La imagen es deliberadamente impactante: morir ahogado con una piedra masiva atada al cuello sería preferible al juicio que aguarda a quienes destruyen la fe de los pequeños de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72586, 'spa', 'Molino o piedra de molino', 'Molino o piedra de molino empleada para moler grano, usada tanto en sentido literal como en calidad de símbolo dramático de juicio catastrófico. Jesús advierte que quien haga tropezar a un niño merece ser ahogado con una piedra de molino al cuello (Mt 18:6; Mr 9:42). En Mt 24:41, dos mujeres moliendo ilustran la repentina separación venidera. En Apocalipsis, el ángel arroja una piedra semejante a una gran muela al mar, sellando la destrucción definitiva de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72587, 'spa', 'Ciudad portuaria licia', 'Hechos 27:5 señala a Mira como el lugar donde el grupo de Pablo se transfirió a un barco granero alejandrino con destino a Roma. La precisión de Lucas refleja las rutas de navegación habituales: la navegación costera los condujo a Mira, importante puerto licio donde el centurión encontró el barco que los llevaría hacia Italia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72588, 'spa', 'Miríada o multitud innumerable', 'Una cantidad muy grande, literalmente diez mil, pero frecuentemente usada para una multitud incontable. En Lucas 12:1 describe la presión aplastante de una muchedumbre (''miríadas'' de personas atropellándose); Hechos 21:20 cuenta ''miríadas'' de judíos creyentes; Hebreos 12:22 contempla ''miríadas de ángeles'' en la Jerusalén celestial. Judas 1:14 profetiza la venida del Señor con ''decenas de millares de sus santos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72595, 'spa', 'Ungir para sepultura', 'Marcos 14:8 presenta la interpretación de Jesús sobre la unción de la mujer como preparación funeraria. La evidencia interlingüística identifica uniformemente la acción de ungir. Jesús reinterpreta proféticamente el acto de devoción: ella ha ungido de antemano su cuerpo para la sepultura, realizando sin saberlo el servicio funerario que las circunstancias posteriores impedirían.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72596, 'spa', 'Miríada o incontable', 'Diez mil, o por extensión, incontable o innumerable: un número muy grande, a menudo indefinido. Mateo 18:24 lo emplea para una deuda impagable. Primera Corintios 4:15 contrasta un solo padre con μυρίοι (incontables) tutores. Primera Corintios 14:19 prefiere cinco palabras inteligibles a diez mil ininteligibles. Puede ser literal (10.000) o hiperbólico (innumerable).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72597, 'spa', 'De ungüento', 'De ungüento: ungüento o aceite perfumado en el contexto de la unción — la costosa preparación aromática derramada sobre la cabeza de Jesús o usada en actos devocionales. La mujer con el frasco de alabastro (Mt 26:7, 12; Mc 14:3-5) y el ungüento que los discípulos dijeron podría venderse por trescientos denarios (Jn 12:3, 5) representan este sentido central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72599, 'spa', 'Con ungüento', 'Con ungüento: ungüento aplicado al cuerpo en actos de devoción personal y hospitalidad, distinguido del sentido 1 por su énfasis en la aplicación íntima y corporal más que en la ceremonia de unción propiamente dicha. La mujer pecadora que bañó con lágrimas los pies de Jesús y los ungió ''con ungüento'' (Lc 7:38, 46), y María de Betania que ungió sus pies (Jn 11:2), emplean μύρον en un contexto de ternura personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72600, 'spa', 'Ungüento (mercancía)', 'Ungüento (mercancía): ungüento como mercancía comercial, incluido entre los bienes de lujo de los mercaderes de Babilonia en el catálogo de juicio apocalíptico de Ap 18:13, junto a la canela, las especias, el incienso y el olíbano. Aquí μύρον funciona no como instrumento devocional sino como índice de riqueza comercial y exceso imperial, cuya destrucción simboliza el colapso del poder mundano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72602, 'spa', 'Una verdad divina o plan redentor antes oculto pero ahora revelado por medio de ', 'Una verdad divina o plan redentor antes oculto pero ahora revelado por medio de Cristo y el Espíritu. En los Sinópticos, Jesús concede a los discípulos percepción del «misterio del reino» negada a los de fuera (Mt 13:11; Mr 4:11; Lc 8:10). Pablo transforma el término en sello distintivo de su teología: la inclusión de los gentiles como coherederos (Ef 3:3-6), la morada de Cristo entre las naciones (Col 1:27) y el propósito eterno de Dios consumado en la plenitud de los tiempos (Ef 1:9-10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72606, 'spa', 'Miopía espiritual', '2 Pedro 1:9 emplea este término metafóricamente para describir la cortedad de vista espiritual de quien carece de virtudes cristianas en crecimiento. La imagen es elocuente: tal persona es espiritualmente ciega, incapaz de percibir la realidad de su purificación del pecado, sin alcanzar a ver las promesas de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72607, 'spa', 'Herida de flagelación', 'La única aparición neotestamentaria se refiere específicamente a las heridas que Cristo recibió durante su flagelación antes de la crucifixión. Las glosas multilingües enfatizan consistentemente la lesión (inglés wound, español herida, alemán Wunde), capturando la realidad física de los azotes mientras apuntan a su propósito salvífico. Pedro ancla la sanación en el sufrimiento concreto y corporal de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72609, 'spa', 'Mancha moral comunitaria', 'Se aplica a personas cuya conducta acarrea deshonra moral sobre la comunidad cristiana. La evidencia multilingüe se divide entre las acepciones abstractas de ''manchas'' o ''defectos'' y el sentido concreto implícito de contaminación moral. El dominio (Actitudes y Emociones) refleja la naturaleza evaluativa del término: es un juicio sobre el carácter, no una mera descripción de error.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72610, 'spa', 'Volverse insípido o necio', 'Perder el sabor, volverse insípido o desabrido, dicho de la sal que ha perdido su cualidad esencial y por tanto su utilidad. Jesús advierte en Mt 5:13 y Lc 14:34 que la sal que se ha «vuelto necia» (queda sin sabor) no puede restaurarse. Este sentido concreto de pérdida de sabor funciona como metáfora del discipulado que ha perdido su propósito distintivo. Pablo extiende el uso al plano intelectual: Dios convierte en necedad la sabiduría del mundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72611, 'spa', 'Necedad o insensatez', 'Necedad o insensatez, la cualidad de ser absurdo o de carecer de sabiduría. Las cinco apariciones neotestamentarias se agrupan en 1 Corintios, donde Pablo construye una paradoja sostenida: el mensaje de la cruz se presenta como μωρία para los que se pierden, pero es poder de Dios (1 Co 1:18). Pablo invierte el juicio en 1 Co 3:19, declarando que la sabiduría del mundo es necedad ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72612, 'spa', 'Habla moralmente necia', 'Designa un tipo de discurso caracterizado por la necedad moral más que por la deficiencia intelectual. Las glosas multilingües oscilan entre lo concreto (''habla necia'' en inglés, ''necedad'' en español) y lo más abstracto. La preocupación de Pablo es ética: tal conversación resulta incompatible con la acción de gracias y la sabiduría que deben distinguir a la comunidad cristiana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72613, 'spa', 'Necio, insensato', 'Necio, insensato: falto de sabiduría, juicio o sentido moral, aplicado a personas (las vírgenes insensatas, Mt 25:2; el constructor sobre la arena, Mt 7:26) y sustantivado como ''necedad'' (1 Co 1:25, 27). Las traducciones convergen en un solo sentido indiferenciado de insensatez moral e intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72620, 'spa', 'Moisés (figura bíblica)', 'Nombre propio del legislador y profeta preeminente de Israel, empleado tanto como referencia personal (la Transfiguración, Mt 17:3) como metonimia de los escritos mosaicos y su código legal («la ley de Moisés», Jn 7:23; Hch 28:23). En Lc 16:29 y 2 Co 3:15, «Moisés» designa el Pentateuco mismo, revelando cuán profundamente se fusionaron la persona y su legado literario en el judaísmo y el cristianismo primitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72631, 'spa', 'Nombre propio', 'Naasón, hijo de Aminadab, líder de la tribu de Judá y antepasado del rey David y de Jesucristo. Aparece en las genealogías de Mateo y Lucas (Mt 1:4; Lc 3:32). Su nombre proviene del hebreo נַחְשׁוֹן, y los textos bíblicos destacan su papel como jefe tribal durante el éxodo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72632, 'spa', 'Nombre propio genealógico', 'Nombre personal que aparece exclusivamente en la genealogía lucana. Las glosas multilingües preservan el nombre con variaciones fonéticas menores (español ''Nangaí'', francés ''Naggaï''), reflejando distintas convenciones de transcripción para nombres griegos. La clasificación de dominio (Nombres) es directa; la importancia reside en su ubicación genealógica más que en su significado léxico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72633, 'spa', 'Nazaret, Nazará (topónimo)', 'Nazaret, Nazará (topónimo): la ciudad de la baja Galilea donde Jesús se crió, escrita de diversas formas como Nazaret y Nazará en los manuscritos. Las doce apariciones designan la misma localidad, desde la Anunciación (Lc 1:26) hasta la partida de Jesús hacia su ministerio (Mc 1:9). Las traducciones confirman un único topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72637, 'spa', 'Nazareno, de Nazaret', 'Adjetivo gentilicio que designa a Jesús como natural de Nazaret en la baja Galilea. Empleado como título identificativo (''Jesús el Nazareno'') tanto por hablantes humanos como por demonios en Marcos y Lucas. La traducción uniforme en diversas lenguas — español ''Nazareno'', alemán ''Nazarener'', francés ''Nazarénien'' — preserva el origen toponímico. Las seis ocurrencias neotestamentarias se aplican exclusivamente a Jesús, funcionando como un apellido de facto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72640, 'spa', 'Nazareno (título de Jesús / sus seguidores)', 'Nazareno (título de Jesús / sus seguidores): designación que significa ''de Nazaret,'' que funciona como título de Jesús y como nombre grupal para sus seguidores. Aparece en la cruz (Jn 19:19), en la proclamación y sanación apostólica (Hch 2:22; 3:6; 4:10), en la autoidentificación de Jesús ante Pablo (Hch 22:8) y como etiqueta del movimiento cristiano primitivo (Hch 24:5, ''la secta de los nazarenos''). La evidencia multilingüe transliterá más que traduce el término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72645, 'spa', 'Antepasado davídico de Jesús', 'Se refiere a Natán, hijo de David, antepasado en la genealogía lucana de Jesús (Lucas 3:31). El nombre se conserva uniformemente en todos los idiomas, dado su reconocimiento como nombre hebreo ampliamente conocido. Su ubicación genealógica es teológicamente significativa: el trazado de Lucas a través de Natán en vez de Salomón resalta la conexión de Jesús con David fuera de la problemática sucesión real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72646, 'spa', 'Natanael (nombre propio)', 'Nombre personal de un discípulo procedente de Caná de Galilea, presentado a Jesús por Felipe (Juan 1:45-49) y presente en la aparición junto al mar de Tiberíades (Juan 21:2). El étimo hebreo netanel (''don de Dios'') se conserva en todas las traducciones. Su encuentro con Jesús avanza desde la duda inicial hasta la confesión culminante como Hijo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72647, 'spa', 'Si, ciertamente', 'Si, ciertamente. Respuesta afirmativa enfatica o confirmacion solemne: ''si, en verdad, ciertamente''. Se usa tanto en respuestas directas a preguntas (Mt 9:28; 13:51) como en intensificador retorico que afirma verdad profetica (Mt 11:9). Las traducciones lo vierten uniformemente como un simple afirmativo (frances ''oui'', espanol ''si''), pero en contexto a menudo lleva el peso de una declaracion teologica, como cuando Pablo llama a Cristo el ''Si'' definitivo de las promesas de Dios (2 Co 1:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72649, 'spa', 'Aldea galileana bíblica', 'Nombre geográfico que designa la aldea en Galilea donde Jesús realizó un notable milagro de resurrección. Las glosas multilingües preservan el nombre con variaciones fonéticas (español ''Naín'', francés ''Naïn''). La clasificación de dominio (Nombres de Personas y Lugares) refleja su función como identificador geográfico y no como sustantivo común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72650, 'spa', 'Templo, santuario (recinto sagrado interior)', 'Templo, santuario (recinto sagrado interior). El santuario interior o templo propiamente dicho como morada de la deidad, abarcando 44 de 45 apariciones. Se usa para el lugar santo del templo de Jerusalen (Mt 23:16-17), para el cuerpo de Cristo (Jn 2:19-21), para los creyentes corporativamente (1 Co 3:16-17; 2 Co 6:16) y para el templo celestial en Apocalipsis (11:19; 15:5-8). El espanol alterna entre ''santuario'' y ''templo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72653, 'spa', 'Santuario pagano o hecho a mano', 'Santuario pagano o hecho a mano. Santuario en miniatura o modelo de templo, especificamente las replicas de plata del templo de Artemisa fabricadas por Demetrio el platero en Efeso (Hch 19:24). Es el unico uso pagano y comercial de ναός en el Nuevo Testamento. El contexto diminutivo y plural (ναοὺς ἀργυροῦς, ''santuarios de plata''), junto con el entorno pagano, distingue este sentido del sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72654, 'spa', 'Nombre personal genealógico', 'Nombre propio en la genealogía lucana, distinto del profeta Nahúm. Las traducciones multilingües reflejan variaciones de transliteración (español ''Naoúm'', francés ''Nahum''). Su peso teológico radica en la función genealógica: el linaje humano de Jesús queda anclado en la historia pactual de Israel, incluso a través de generaciones conocidas solo por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72656, 'spa', 'Nombre personal romano', 'Nombre propio que designa a un romano cuyos miembros del hogar eran cristianos. Las traducciones multilingües conservan ''Narciso'' con variaciones fonéticas (español ''Narkíssou'', francés ''Narcisse''). Su relevancia social radica en la posible conexión con un liberto imperial, lo cual enriquece el contexto histórico de la expansión del cristianismo primitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72658, 'spa', 'Capitán o naviero', 'Se refiere específicamente al capitán o patrón del barco en el viaje de Pablo a Roma. Las traducciones multilingües enfatizan propiedad y mando (español ''dueño del barco'', francés ''armateur''). El dominio Artefactos resulta algo impreciso, ya que el término designa a una persona con un rol social vinculado a embarcaciones, no a la nave misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72659, 'spa', 'Nave o embarcación', 'Designa el gran barco granero que transportaba a Pablo a Roma y que naufragó en la costa de Malta. Las traducciones multilingües rinden uniformemente ''nave'' o ''barco'' (español ''nave'', francés ''navire''). El dominio Artefactos es apropiado, aunque el registro literario y la prosapia clásica del término le confieren un tono ligeramente elevado frente al más prosaico πλοῖον.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72660, 'spa', 'Marineros', 'Marineros, navegantes u hombres de mar: quienes se dedican profesionalmente a trabajar a bordo de embarcaciones. Hechos 27:27, 30 describe a los marineros del barco de Pablo intentando abandonar la nave durante la tormenta. Apocalipsis 18:17 los incluye entre quienes lloran el colapso económico de Babilonia. El griego ναύτης deriva de ναῦς (nave).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72661, 'spa', 'Nombre patriarcal genealógico', 'Nombre propio del abuelo de Abraham en la genealogía lucana. Las traducciones multilingües conservan ''Nacor'' o ''Nahor'' con ligeras variaciones fonéticas (español ''Nachṓr'', francés ''Nachor''). El dominio Nombres de Personas y Lugares refleja su función como identificador genealógico que vincula a Jesús con las narrativas patriarcales del Génesis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72662, 'spa', 'Hombre joven', 'Varón joven o mozo, en la etapa de la primera adultez marcada por vigor y fuerza. Las tres apariciones neotestamentarias están en Hechos: Saulo en el martirio de Esteban (7:58), Eutico que cayó de la ventana (20:9) y el sobrino de Pablo que advirtió de la emboscada (23:17). El griego νεανίας destaca la fase activa y juvenil entre la adolescencia y la madurez establecida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72663, 'spa', 'Hombre joven en la plenitud de su vigor físico, desde la adolescencia tardía has', 'Hombre joven en la plenitud de su vigor físico, desde la adolescencia tardía hasta el comienzo de la edad adulta. Se aplica al joven rico (Mt 19:20, 22), al joven que huyó desnudo de Getsemaní (Mr 14:51), al hijo muerto de la viuda de Naín (Lc 7:14) y a Eutico que cayó de la ventana (Hch 20:9). La profecía de Joel citada en Hch 2:17 promete que los jóvenes verán visiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72668, 'spa', 'Naamán el sirio', 'Se refiere al comandante militar sirio cuya sanación se relata en 2 Reyes 5 y que Jesús cita como precedente profético de la inclusión gentil. Las glosas multilingües traducen el nombre uniformemente (español ''Naamán'', francés ''Naaman''), reflejando su condición de figura veterotestamentaria conocida. Su importancia teológica radica en la soberanía de Dios al elegir a quién conceder gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72669, 'spa', 'los muertos (personas)', 'Los muertos como sustantivo colectivo — personas difuntas consideradas como grupo, especialmente en contextos escatológicos y de resurrección. Central en la proclamación neotestamentaria: ''Dios le levantó de los muertos'' (Ro 10:9), ''la resurrección de los muertos'' (1 Co 15:12-21), ''juzgar a vivos y muertos'' (2 Ti 4:1). Las 111 apariciones se concentran fuertemente en Pablo y Hechos. Todas las lenguas receptoras usan formas sustantivadas del adjetivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72670, 'spa', 'muerto, sin vida', 'Muerto como adjetivo que describe a una persona o cosa en estado de muerte, literal o metafórico. Literalmente: el muchacho parecía muerto (Mr 9:26), el hijo de la viuda se incorporó (Lc 7:15), Ananías cayó muerto (Hch 5:10). Figuradamente: el pródigo estaba ''muerto y ha vuelto a vivir'' (Lc 15:24, 32), el cuerpo de Abraham ''como muerto'' (Ro 4:19), y la fe sin obras está ''muerta'' (Stg 2:17, 26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72679, 'spa', 'Mortificar, dar muerte', 'Hacer morir, dejar sin vida o mortificar, ya sea describiendo un estado de muerte o mandando eliminar activamente el pecado. Romanos 4:19 y Hebreos 11:12 usan νεκρόω para la capacidad reproductiva «amortecida» de Abraham. Colosenses 3:5 ordena a los creyentes «hacer morir» las pasiones terrenales. El término abarca desde el estado pasivo de muerte hasta la mortificación activa del pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72681, 'spa', 'Nuevo o fresco, describiendo cosas recientemente hechas o producidas en contrast', 'Nuevo o fresco, describiendo cosas recientemente hechas o producidas en contraste con lo viejo o gastado. La parábola de los odres gira en torno a echar vino nuevo (νέος οἶνος) en odres nuevos (Mt 9:17; Mr 2:22; Lc 5:37-38). Pablo llama a los corintios «nueva masa» (1 Co 5:7) y contrasta el «nuevo hombre» renovado en conocimiento (Col 3:10). Hebreos 12:24 habla de la sangre del «nuevo pacto». El español «nuevo/nueva» cubre plenamente esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72682, 'spa', 'Joven o más joven en edad, usado tanto como adjetivo como sustantivo referido a ', 'Joven o más joven en edad, usado tanto como adjetivo como sustantivo referido a personas. El pródigo es el hijo «más joven» (Lc 15:12-13), el «más joven» debe servir al mayor (Lc 22:26), y las Epístolas Pastorales instruyen a los hombres y mujeres más jóvenes (1 Ti 5:1, 11; Tit 2:4, 6; 1 Pe 5:5). El español «jóvenes/más joven» y la forma comparativa νεώτερος, que domina este sentido, confirman la referencia a la edad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72686, 'spa', 'La forma femenina Νέαν usada como elemento geográfico en el compuesto Neápolis (', 'La forma femenina Νέαν usada como elemento geográfico en el compuesto Neápolis («Ciudad Nueva») en Hechos 16:11, nombrando el puerto macedonio (moderna Kavala, Grecia) donde Pablo, Silas y Timoteo desembarcaron tras la visión del varón de Macedonia. Es un topónimo fijado más que un adjetivo vivo, pero preserva el significado adjetival original de «nueva».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72689, 'spa', 'Pichones sacrificiales', 'Se refiere a los pichones jóvenes ofrecidos como sacrificio en el templo por María y José. Las glosas multilingües varían entre ''jóvenes'' (inglés) y términos de aves (español ''pichones'', francés ''poussin''). El dominio asignado (Personas) parece erróneo, ya que se trata de aves, aunque la extensión metafórica a seres humanos jóvenes existe en la literatura clásica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72690, 'spa', 'Período de juventud', 'El período de la vida temprana, desde la niñez hasta la adultez joven, considerado como etapa formativa del carácter y los hábitos. En Mr 10:20 y Lc 18:21, los hablantes citan su juventud como punto de partida de la observancia de la Torá. Pablo apela a ella como evidencia biográfica en Hch 26:4. En 1 Ti 4:12, Pablo invierte el enfoque nostálgico habitual: la juventud de Timoteo no es una credencial sino un posible objeto de desprecio que debe superarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72691, 'spa', 'Recién convertido', 'Designa a una persona recientemente convertida al cristianismo, que carece de la madurez y experiencia necesarias para el liderazgo. Las glosas multilingües captan tanto la metáfora agrícola (''recién plantado'', implícita en la raíz) como la aplicación eclesiástica (inglés ''new convert'', español ''recién convertido'', alemán ''Neubekehrter''). El dominio (Tiempo) refleja el aspecto temporal, aunque la dimensión eclesiológica es igualmente central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72693, 'spa', 'Masa atmosférica de vapor de agua condensado que en el uso bíblico lleva consist', 'Masa atmosférica de vapor de agua condensado que en el uso bíblico lleva consistentemente significado teofánico y escatológico. La nube que cubre a los discípulos en la Transfiguración (Mt 17:5; Mr 9:7; Lc 9:34) retoma el motivo de la columna de nube del Éxodo, mientras que las nubes de la Parusía (Mt 24:30; Ap 1:7) señalan la intervención divina final. Las traducciones usan uniformemente cognados — español «nube», francés «nuée» — confirmando un campo semántico unitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72696, 'spa', 'Neftalí, tribu y territorio', 'Neftalí, hijo de Jacob y ancestro tribal, y por extensión la tribu y el territorio que llevan su nombre. Mateo 4:13, 15 cita la profecía de Isaías sobre «la tierra de Neftalí» donde Jesús inició su ministerio en Galilea. Apocalipsis 7:6 nombra a Neftalí entre los 144.000 sellados de las tribus de Israel. El hebreo נַפְתָּלִי significa «mi lucha» (Gn 30:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72697, 'spa', 'Nube de testigos', 'Se usa metafóricamente para designar la gran compañía de santos veterotestamentarios que dan testimonio de la vida de fe. Las glosas multilingües conservan el sentido literal ''nube'' (español ''nube'', alemán ''Wolke''), permitiendo que el sentido figurado emerja del contexto. El dominio (Objetos geográficos) corresponde al significado atmosférico literal, pero no capta la extensión metafórica a multitudes humanas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72698, 'spa', 'Sede interior del alma', 'Se refiere metafóricamente a los pensamientos, motivaciones y afectos más íntimos que solo Dios puede conocer y juzgar. Las glosas multilingües oscilan entre la anatomía literal (español ''riñones'', francés/alemán ''Nieren'') y la interpretación metafórica (inglés ''minds''). El dominio (Partes del cuerpo) capta el referente literal pero no la carga metafórica: aquí los riñones simbolizan la conciencia moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72699, 'spa', 'Guardiana del templo', 'Se refiere al papel de Éfeso como ciudad guardiana y anfitriona del templo de Artemisa. Las traducciones multilingües enfatizan la custodia (inglés ''temple keeper'', español ''guardiana del templo'', francés ''gardien du temple''). Se trata de un título cívico-religioso y un rol social, más apropiado para los dominios de Religión o Estructura Social que para el dominio asignado de Naturaleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72700, 'spa', 'Pasiones juveniles', 'Describe las pasiones o deseos característicos de la juventud de los cuales Timoteo debe huir. Las traducciones multilingües enfatizan la relación con la edad (inglés ''youthful'', español ''juveniles'', alemán ''jugendlich''). El dominio de Tiempo refleja el aspecto temporal de tentaciones propias de una etapa de la vida, aunque la dimensión moral de Actitudes y Emociones es igualmente prominente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72701, 'spa', 'Partícula de juramento', 'Funciona como partícula de juramento que introduce aquello por lo cual Pablo jura para validar su afirmación. Las traducciones multilingües preservan la fuerza preposicional (inglés ''by'', español ''por'', alemán ''bei''), aunque el contexto formulaico de juramento resulta menos familiar en el lenguaje moderno. Se trata de una partícula discursiva, más adecuada para los dominios de Comunicación o Modalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72703, 'spa', 'Inmadurez infantil', 'Describe el pensamiento inmaduro e infantil que Pablo reprende en los corintios. Las traducciones multilingües expresan el verbo como un mandato de permanecer como niños (español ''sed niños'', francés ''être enfant'', alemán ''Kinder sein''). El dominio de Personas es parcialmente adecuado, aunque el término describe una cualidad conductual (inmadurez) más que una categoría social propiamente dicha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72704, 'spa', 'Infante, niño pequeño', 'Infante, niño pequeño: literalmente un bebé o niño muy pequeño. Jesús agradece al Padre por revelar la verdad a los νήπιοι (Mt 11:25; Lc 10:21), y Pablo llama a los corintios infantes en Cristo (1 Co 3:1). Las traducciones convergen en la imagen de alguien demasiado pequeño para razonar. Romanos 2:20 lo usa para los espiritualmente inexpertos que aún necesitan guía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72709, 'spa', 'Inmaduro, infantil', 'Inmaduro, infantil: inmadurez espiritual o intelectual. En Gálatas 4:1-3, Pablo compara al heredero que aún es menor (νήπιος) con los creyentes bajo la tutela del antiguo pacto. El contexto cambia claramente de la edad física a la etapa de desarrollo en la comprensión. El contraste con los herederos maduros hace que la metáfora sea incisiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72710, 'spa', 'Tierno, delicado', 'Tierno, delicado: tierno y suave como una madre que amamanta. En 1 Tesalonicenses 2:7, una variante textual produce ''fuimos tiernos (νήπιοι) entre vosotros, como una nodriza que cuida a sus hijos.'' Este sentido es raro y debatido. Aquí la imagen infantil se invierte: Pablo se convierte en el cuidador tierno, no en el bebé. Solo una aparición sustenta esta lectura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72714, 'spa', 'Nombre propio cristiano', 'Nombre personal que identifica a un cristiano en Roma saludado por Pablo. Las traducciones multilingües preservan ''Nereus'' con ligeras variaciones fonéticas (español ''Nēréa'', francés ''Néréus''), reflejando el origen clásico del nombre proveniente de la mitología griega. El dominio de Nombres de Personas y Lugares es directo; la importancia radica en las redes sociales y eclesiales implícitas en el saludo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72715, 'spa', 'Nombre personal genealógico', 'Nombre propio en la genealogía lucana, posiblemente relacionado con el hebreo Nerías. Las traducciones multilingües lo preservan de forma consistente (español ''Nērí'', francés ''Néri''), reflejando su origen semítico. Su peso teológico radica en la función genealógica: el linaje de Jesús incluye tanto antepasados célebres como olvidados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72716, 'spa', 'Islote o isla pequeña', 'Se refiere específicamente a la pequeña isla de Cauda que ofreció refugio temporal durante el viaje de Pablo. Las traducciones multilingües oscilan entre términos genéricos de ''isla'' y diminutivos que enfatizan el tamaño (español ''islita''). El dominio (Objetos y Características Geográficas) es apropiado para este referente geográfico concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72717, 'spa', 'Isla', 'Una masa de tierra rodeada de agua. En Hechos, el término ancla la narrativa geográficamente mientras Pablo navega entre islas del Mediterráneo: la nave debe encallar en ''alguna isla'' (Hechos 27:26), identificada como Malta (Hechos 28:1), donde el funcionario principal Publio los hospeda (Hechos 28:7). En Apocalipsis, sin embargo, las islas adquieren dimensión escatológica, huyendo ante la presencia divina como símbolo de la disolución del orden creado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72719, 'spa', 'Ayuno (disciplina espiritual)', 'Práctica de abstenerse voluntariamente de alimento como disciplina espiritual. Se emplea en singular y plural en el NT para describir el ayuno que acompaña a la oración, el duelo o la consagración. Ana adoraba con ayunos noche y día (Luc 2:37), y la iglesia de Antioquía ayunó antes de enviar a Pablo y Bernabé (Hch 13:2-3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72721, 'spa', 'El Ayuno (Yom Kippur)', 'El ayuno calendárico específico de Yom Kippur, el Día de la Expiación, usado como referencia temporal en Hechos 27:9 para indicar que la navegación era peligrosa porque la festividad otoñal ya había pasado. El artículo definido en griego (τὴν νηστείαν) y la mayúscula en las traducciones distinguen este uso del ayuno ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72723, 'spa', 'Abstenerse voluntariamente de alimento como disciplina espiritual, expresando tí', 'Abstenerse voluntariamente de alimento como disciplina espiritual, expresando típicamente devoción, arrepentimiento, duelo o preparación para la dirección divina. El ayuno de cuarenta días de Jesús (Mt 4:2) establece el modelo, mientras que su enseñanza en el Sermón del Monte (Mt 6:16-18) reforma la práctica advirtiendo contra la piedad ostentosa. La iglesia primitiva continuó la tradición antes de decisiones importantes (Hch 13:2-3). El español ''ayunar'' refleja directamente esta práctica de abstinencia deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72734, 'spa', 'Sobrio, temperante', 'Sobrio, temperante o de mente clara, caracterizado por el dominio propio y la ausencia de embriaguez o exceso. El término νηφάλιος/νηφάλεος es un requisito para los líderes de la iglesia (1 Ti 3:2, 3:11) y los ancianos (Tit 2:2), abarcando tanto la sobriedad literal como la templanza metafórica: disciplina mental y equilibrio. El español «sobrio» preserva fielmente este doble significado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72736, 'spa', 'Ser sobrio, vigilar', 'Mantener dominio propio lúcido y alerta espiritual, especialmente ante el retorno de Cristo o el peligro espiritual. La extensión metafórica desde la abstinencia de vino hasta la vigilancia mental es completa en el NT: Pablo contrasta al creyente sobrio con quienes ''duermen'' o están ''ebrios'' en la noche escatológica (1 Tes 5:6-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72740, 'spa', 'Sobrenombre latino personal', 'Sobrenombre latino que identifica a Simeón, uno de los líderes de la iglesia de Antioquía. Las traducciones multilingües preservan ''Níger'' de forma uniforme, reflejando el origen latino del término. La diversidad cultural y étnica implícita en el nombre enriquece nuestra comprensión de la composición social del cristianismo primitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72741, 'spa', 'Nombre personal bíblico', 'Nombre propio que identifica a uno de los siete varones elegidos para el servicio en la iglesia de Jerusalén. Las traducciones multilingües preservan ''Nicanor'' con variaciones fonéticas según la lengua, reflejando el origen griego. Su importancia eclesial reside en el papel que desempeñó como puente entre las comunidades hebraica y helenista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72742, 'spa', 'El sentido activo de conquistar, vencer o prevalecer — ya sea en guerra espiritu', 'El sentido activo de conquistar, vencer o prevalecer — ya sea en guerra espiritual, lucha moral o conflicto cósmico. La declaración de Jesús «Yo he vencido al mundo» (Jn 16:33) ancla este uso. Las epístolas juaninas celebran la victoria de los creyentes sobre el maligno (1 Jn 2:13-14; 4:4; 5:4-5). Apocalipsis emplea νικάω como verbo programático: el que vence recibe el árbol de la vida, la corona y el trono (Ap 2-3), y el Cordero ha vencido (Ap 5:5; 17:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72753, 'spa', 'El sentido pasivo de ser vencido, conquistado o derrotado por una fuerza contrar', 'El sentido pasivo de ser vencido, conquistado o derrotado por una fuerza contraria. Romanos 12:21a advierte μὴ νικῶ ὑπὸ τοῦ κακοῦ — «no seas vencido por el mal» — usando la voz pasiva para mostrar al creyente como potencialmente derrotado si responde con represalia en lugar de con el bien. El español «seas vencido» preserva la voz pasiva con claridad. Este sentido aparece como contraparte negativa de la victoria activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72758, 'spa', 'Victoria espiritual', 'Se refiere a la victoria espiritual sobre el mundo que la fe en Jesús logra. Las traducciones multilingües preservan uniformemente términos de ''victoria'' (español ''victoria'', alemán ''Sieg''), captando la metáfora bélica. La paradoja joánica es que la fe, no la fuerza militar, gana la guerra decisiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72759, 'spa', 'Nicodemo, fariseo joánico', 'Nicodemo, individuo identificado por nombre: fariseo y principal entre los judíos que aparece tres veces en el Evangelio de Juan. Su trayectoria desde visitante nocturno secreto (Jn 3:1) hasta defensor público de la justicia (Jn 7:50) y participante en la sepultura de Jesús (Jn 19:39) constituye uno de los arcos narrativos más cuidadosamente desarrollados del Cuarto Evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72761, 'spa', 'Nombre personal', 'Nombre propio que identifica al último de los siete elegidos en Hechos 6, notable por ser un converso gentil. Las glosas multilingües preservan uniformemente «Nicolaus» o «Nicolas» (en español «Nikólaos», en francés «Nicolas»), reflejando el nombre griego. El dominio (Nombres) es correcto; el detalle histórico de ser prosélito de Antioquía señala el horizonte cultural en expansión de la iglesia primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72762, 'spa', 'Nombre geográfico', 'Nombre de lugar que designa la ciudad donde Pablo pretendía pasar el invierno, muy probablemente en Epiro. Las glosas multilingües preservan uniformemente «Nicopolis» o «Nikopolis» (en español «Nikópolis», en alemán «Nikopolis»), reflejando el nombre griego. El dominio más adecuado sería Geografía o Nombres de Lugares, ya que se trata de un topónimo, no una categoría de naturaleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72763, 'spa', 'Victoria decisiva', 'Triunfo decisivo y completo, particularmente la conquista final de Dios sobre los poderes hostiles. En Mt 12:20 designa el éxito definitivo de la justicia (citando Is 42:3 LXX, donde νῖκος traduce el hebreo לָנֶצַח). En 1 Co 15:54-57 aparece tres veces cuando Pablo declara la muerte absorbida en victoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72764, 'spa', 'Ninivitas', 'Los ninivitas, habitantes de Nínive, la gran ciudad asiria a la que Jonás predicó. Jesús los invoca como testigos de condenación: se arrepintieron ante el mensaje de Jonás, pero los contemporáneos de Jesús rechazan a uno mayor que Jonás (Mt 12:41; Lc 11:30, 32). El griego Νινευίτης designa al pueblo por su ciudad. Su arrepentimiento ejemplar, siendo paganos, contrasta con la dureza de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72765, 'spa', 'Palangana para lavar', 'Se refiere a la palangana que Jesús usó al lavar los pies de los discípulos en la Última Cena. Las glosas multilingües preservan «palangana» o «recipiente para lavar» (en español «vasija», en francés «bassin», en alemán «Waschbecken»). El dominio más preciso sería Artefactos, ya que se trata de un utensilio doméstico, no de una categoría natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72766, 'spa', 'Lavar una parte específica del cuerpo — manos, pies o rostro — ya sea por higien', 'Lavar una parte específica del cuerpo — manos, pies o rostro — ya sea por higiene cotidiana, pureza ceremonial u hospitalidad. El lavado de los pies de los discípulos por parte de Jesús (Jn 13:5-14) transforma una costumbre doméstica en modelo de servicio humilde, mientras que la insistencia de los fariseos en el lavado de manos antes de comer (Mc 7:3) refleja preocupaciones de pureza ritual. El español ''lavar'' abarca bien este sentido de limpieza física parcial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72779, 'spa', 'Entender o percibir mentalmente', 'Entender o percibir mentalmente: captar algo mediante el ejercicio de la mente y no solo por la vista o el oído. Se usa para el fracaso de los discípulos en comprender los milagros de los panes (Mt 15:17; 16:9, 11; Mr 7:18; 8:17), la invitación a discernir la abominación desoladora (Mt 24:15; Mr 13:14, ''el que lee, entienda''), y la aprehensión mental de la naturaleza invisible de Dios a través de la creación (Ro 1:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72788, 'spa', 'Mente, pensamiento', 'La facultad o contenido de la actividad mental: la mente, los pensamientos o las percepciones. En 2 Cor 3:14, los νοήματα de Israel fueron endurecidos, incapaces de percibir la gloria que se desvanecía; en 2 Cor 4:4, el dios de este siglo ciega las mentes de los incrédulos; y en Fil 4:7, la paz de Dios guarda corazón y νοήματα.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72789, 'spa', 'Ardid, maquinación', 'Un plan astuto, estratagema o designio malintencionado, atribuido particularmente a Satanás. En 2 Cor 2:11, Pablo insta a los corintios a perdonar al ofensor ''para que Satanás no se aproveche de nosotros, pues no ignoramos sus νοήματα'' — sus maquinaciones. El español ''designios'', el inglés ''schemes'' y el alemán ''Anschläge'' captan la cualidad deliberada y adversarial de esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72792, 'spa', 'Hijo ilegítimo', 'Usado metafóricamente para quienes carecen de una relación filial genuina con Dios, evidenciada por su exención de la disciplina divina. Las glosas multilingües preservan el término legal «ilegítimo» o «bastardo» (en español «bastardos», en alemán «unecht» que significa «espurio»). El dominio apropiado sería Parentesco o Legitimidad, ya que se trata de una categoría jurídica y social, no fisiológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72794, 'spa', 'Pensar, suponer o creer algo, a menudo una creencia que resulta equivocada o nec', 'Pensar, suponer o creer algo, a menudo una creencia que resulta equivocada o necesita corrección. Jesús abre enseñanzas clave con ''no penséis'' (Mt 5:17; 10:34), mientras Lucas registra suposiciones ordinarias (Lc 2:44) y Pablo expresa la confianza de Moisés en que sus compatriotas comprenderían (Hch 7:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72805, 'spa', 'Ser considerado o tenido por algo (sentido pasivo)', 'Ser considerado o tenido por algo (sentido pasivo). Su única aparición neotestamentaria en Lucas 3:23 —''Jesús era tenido por (ἐνομίζετο) hijo de José''— tiene un peso teológico profundo: la suposición pública de paternidad josefina se mantiene en tensión silenciosa con el nacimiento virginal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72806, 'spa', 'Experto en la Ley', 'Designa a una persona profesionalmente formada en la Ley mosaica: un jurista, erudito legal o doctor de la Torá. Los Evangelios Sinópticos presentan a estas figuras como intérpretes autorizados que ponen a prueba a Jesús (Lucas 10:25) o rechazan el propósito de Dios (Lucas 7:30). El término subraya la dimensión de enseñanza e interpretación de este rol dentro del judaísmo del Segundo Templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72811, 'spa', 'Legal, relativo a la ley', 'Uso puramente adjetival: ''perteneciente o relativo a la ley''. En Tito 3:9, Pablo advierte contra ''contiendas legales'' (griego: μάχας νομικάς), disputas enraizadas en litigios legalistas en vez de doctrina edificante. Este sentido descriptivo y no personal contrasta marcadamente con el uso sustantivado que predomina en el resto del Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72813, 'spa', 'Moneda acuñada', 'Se refiere al denario romano mostrado a Jesús, con la imagen del emperador grabada. Las glosas multilingües preservan uniformemente «moneda» o «dinero» (en español «moneda», en francés «monnaie»), capturando las implicaciones financieras y legales. El dominio más adecuado sería Artefactos o Economía, ya que las monedas son objetos manufacturados, no sustancias naturales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72814, 'spa', 'Maestro de la ley', 'Maestro o experto en la ley mosaica (Torá), dedicado a la interpretación legal y la instrucción religiosa. Lucas 5:17 los menciona reunidos cuando Jesús sanó al paralítico. Hechos 5:34 identifica al respetado Gamaliel como νομοδιδάσκαλος. Primera Timoteo 1:7 critica a quienes aspiran a este papel sin comprensión. El término designa a eruditos religiosos-legales, equivalentes a los maestros rabínicos posteriores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72815, 'spa', 'Promulgación de la ley', 'Se refiere a la entrega de la ley mosaica en el Sinaí, uno de los privilegios del pacto de Israel. Las glosas multilingües conservan el sentido de «legislación» o «promulgación de la ley» (español «legislación», francés «législation», alemán «Gesetzgebung»), capturando el sentido formal y jurídico. El dominio Comunicación refleja la transmisión de la ley como discurso divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72817, 'spa', 'Legislador divino', 'Se refiere a Dios como la única fuente legítima de la ley moral, en contraste con la presunción humana de juzgar a otros. Las glosas multilingües conservan uniformemente «legislador» (español «legislador», alemán «Gesetzgeber»), enfatizando la autoridad divina. El dominio más apropiado sería Estructuras Sociales o Autoridad, dado que se trata de un rol u oficio de liderazgo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72818, 'spa', 'ley (esp. la Ley mosaica)', 'La ley en general y específicamente la Torá o Ley de Moisés, abarcando el Pentateuco, el canon veterotestamentario más amplio y el principio de ordenanza divina. Aparece con artículo (ὁ νόμος) para el código mosaico concreto y sin él para la ley como principio rector (Ro 7:21-23). Central en la teología paulina, donde funciona como pedagogo (Gá 3:24), revelador del pecado (Ro 7:7) y aquello que Cristo cumple y trasciende.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72825, 'spa', 'Obsesión enfermiza', 'Usado metafóricamente para describir una preocupación morbosa o insana por controversias y disputas. Las glosas multilingües conservan el sentido médico de «estar enfermo» (español «enfermando», alemán «krank sein»), confiando en que el contexto aporte la aplicación figurada. El dominio Procesos Fisiológicos se ajusta al sentido literal, aunque el uso paulino es claramente metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72826, 'spa', 'Enfermedad física', 'Se refiere a la enfermedad o aflicción que se creía que el estanque de Betesda podía curar. Las glosas multilingües conservan terminología médica (español «enfermedad», francés «maladie», alemán «Krankheit»). El dominio Procesos y Estados Fisiológicos es apropiado para esta referencia directa a un padecimiento físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72827, 'spa', 'Enfermedad o dolencia grave como categoría general, usada predominantemente en l', 'Enfermedad o dolencia grave como categoría general, usada predominantemente en las descripciones sinópticas de resumen del ministerio de sanación de Jesús. La fórmula programática ''toda enfermedad y toda dolencia'' (πᾶσαν νόσον καὶ πᾶσαν μαλακίαν) enmarca las campañas galileas de Jesús (Mt 4:23; 9:35) y la autoridad delegada a los Doce (Mt 10:1; Lc 9:1). Mr 1:34 y Lc 4:40; 6:17; 7:21 usan νόσος de forma similar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72831, 'spa', 'Nidada protegida', 'Usado figuradamente para referirse al pueblo de Jerusalén que Jesús deseaba reunir y proteger. Las glosas multilingües conservan términos ornitológicos (español «nidada», francés «couvée»), dejando que la fuerza metafórica emerja de la imagen maternal de Jesús. El dominio Personas refleja la aplicación figurada, aunque la referencia literal es al mundo animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72832, 'spa', 'Polluelos (uso figurado)', 'Se usa figuradamente en el lamento de Jesús por los hijos de Jerusalén, a quienes deseaba proteger como la gallina protege a sus crías. Las traducciones multilingües conservan términos referidos a aves (español ''polluelos'', francés ''couvée'' que significa ''nidada''). El dominio (Personas) refleja el uso figurado, aunque literalmente la palabra designa crías de aves.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72833, 'spa', 'Sustraer o hurtar', 'Retener, sustraer o apropiarse indebidamente de lo que pertenece a otro, con engaño deliberado. Hechos 5:2-3 emplea νοσφίζω para describir la retención fraudulenta que hicieron Ananías y Safira del producto de la venta. Tito 2:10 advierte a los esclavos contra el hurto. El término abarca tanto el acto de tomar como el engaño implicado en ocultarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72834, 'spa', 'Sur, viento del sur', 'El viento del sur o el sur como punto cardinal, significados relacionados pues los vientos se nombraban según su origen. En Lucas 12:55, νότος es el viento cálido del desierto. En Mateo 12:42 y Lucas 11:31 es referencia geográfica a Sabá. Lucas 13:29 lo emplea en la visión escatológica de personas llegando desde los cuatro puntos cardinales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72838, 'spa', 'Amonestación correctiva', 'Amonestación, advertencia o instrucción correctiva: orientación verbal destinada a redirigir el pensamiento o la conducta. Primera Corintios 10:11 presenta las advertencias del Antiguo Testamento como νουθεσία para los creyentes. Efesios 6:4 la empareja con la disciplina en la crianza de los hijos. Tito 3:10 establece un límite: dos amonestaciones y luego separación del divisivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72839, 'spa', 'Amonestar, advertir', 'Aconsejar o advertir a alguien con el propósito de corregir su entendimiento o conducta, combinando exhortación con reprensión suave. La etimología (νοῦς + τίθημι, «poner en la mente») revela su enfoque distintivo: no es simple regaño sino instrucción intencional orientada a reorientar el pensamiento. Pablo lo emplea para el cuidado pastoral sostenido (Hch 20:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72844, 'spa', 'Fiesta de luna nueva', 'Se refiere a la festividad judía de la luna nueva que algunos pretendían imponer a los creyentes gentiles. Las traducciones multilingües conservan términos astronómicos o calendáricos (español ''de luna nueva'', alemán ''Neumond''), señalando el primer creciente visible. El dominio (Tiempo) refleja la naturaleza calendárica y temporal de la observancia, aunque Religión también sería apropiado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72845, 'spa', 'Con sabiduría', 'Describe la calidad de la respuesta del escriba a Jesús sobre el mandamiento más importante. Las traducciones multilingües conservan ''sabiamente'' o ''con entendimiento'' (español ''sabiamente'', francés ''avec sagesse'', alemán ''verständig'' que significa ''inteligentemente''), enfatizando el discernimiento. El dominio (Actitudes y Emociones) es parcialmente adecuado, aunque Cognición o Sabiduría captaría mejor el aspecto intelectual y moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72846, 'spa', 'La mente como sede del pensamiento, el razonamiento moral y la disposición inter', 'La mente como sede del pensamiento, el razonamiento moral y la disposición interior: la orientación interna que moldea la conducta y las creencias. Pablo habla de una mente reprobada (Rom 1:28), de la ley de la mente en guerra contra el pecado (Rom 7:23) y de la renovación de la mente que discierne la voluntad de Dios (Rom 12:2). En Efesios 4:17, los gentiles caminan en la futilidad de su mente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72847, 'spa', 'La mente como facultad de comprensión y conciencia, especialmente la capacidad d', 'La mente como facultad de comprensión y conciencia, especialmente la capacidad de captar significados y verdades espirituales. En Lucas 24:45, el Jesús resucitado abrió el entendimiento de los discípulos para comprender las Escrituras. Pablo contrasta orar con el espíritu y orar con el entendimiento (1 Cor 14:14-15), distinguiendo esta facultad cognitiva de la orientación interior más amplia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72851, 'spa', 'Nombre propio personal', 'Nombre propio que identifica a quien hospedaba una iglesia doméstica en Laodicea, probablemente una mujer. Las traducciones multilingües conservan uniformemente ''Ninfa'' o ''Nýmfa'' (español ''Nýmfa'', francés conservando la forma griega), aunque la ambigüedad de género persiste. El dominio (Nombres de Personas y Lugares) es correcto; el rol eclesial (albergar una congregación) enriquece la historia social del cristianismo primitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72852, 'spa', 'Novia', 'Una novia — mujer en el contexto de su boda o, en sentido metafórico extendido, la iglesia o la ciudad santa como esposa de Cristo. Cinco ocurrencias neotestamentarias llevan este significado, incluyendo Jn 3:29 donde el Bautista habla del gozo del novio al escuchar a la novia, y los pasajes de Apocalipsis sobre la nueva Jerusalén (Ap 21:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72853, 'spa', 'Nuera', 'Una nuera — mujer definida por su relación con los padres de su esposo, no con el novio mismo. Las tres ocurrencias aparecen en el dicho de Jesús sobre la división familiar: Mt 10:35 y Lc 12:53 (dos veces) advierten que la «nuera» se levantará contra su «suegra». El español distingue claramente «nuera» de «novia».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72856, 'spa', 'El hombre que está por casarse o recién casado, el novio en un banquete de bodas', 'El hombre que está por casarse o recién casado, el novio en un banquete de bodas. En los Evangelios Sinópticos, Jesús se identifica como el novio cuya presencia hace inapropiado el ayuno (Mt 9:15; Mc 2:19-20), estableciendo una poderosa metáfora cristológica. La Parábola de las Diez Vírgenes (Mt 25:1-10) construye urgencia escatológica en torno a la llegada tardía del novio. Juan el Bautista se declara explícitamente amigo del novio (Jn 3:29), subordinándose al Cristo venidero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72859, 'spa', 'Cámara nupcial', 'La cámara nupcial, salón de bodas o, por extensión, la celebración y los invitados. En los tres pasajes sinópticos (Mt 9:15; Mr 2:19; Lc 5:34), «hijos de la cámara nupcial» es un semitismo para los invitados o acompañantes del novio. Jesús lo usa para explicar por qué sus discípulos no ayunan: es un banquete de bodas, no un funeral. El griego νυμφών designa tanto el recinto como la compañía festiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72860, 'spa', 'ahora', 'Adverbio temporal que marca el momento presente, la era actual o un punto de giro argumentativo. Más allá de la simple cronología, los autores neotestamentarios despliegan νῦν para resaltar el ''ahora'' escatológico de la acción salvadora de Dios — ''pero ahora, aparte de la ley, se ha manifestado la justicia de Dios'' (Ro 3:21) — y para contrastar la existencia anterior con la transformación presente (Ef 2:13; Col 1:22). Español ahora cubre todo el espectro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72863, 'spa', 'Adverbio temporal-lógico enfático que significa ''ahora'' o ''pero ahora,'' marcando', 'Adverbio temporal-lógico enfático que significa ''ahora'' o ''pero ahora,'' marcando la situación presente como decisivamente diferente de lo que la precedió. Pablo lo emplea en bisagras teológicas fundamentales: la revelación de la justicia de Dios aparte de la ley (Ro 3:21), la libertad del pecado (Ro 6:22) y la liberación de la ley (Ro 7:6). La fuerza contrastiva se capta bien en español con ''pero ahora'' o ''ahora bien,'' subrayando el giro radical que el evangelio introduce en la historia de la salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72864, 'spa', 'noche', 'Período de oscuridad desde el ocaso hasta el amanecer, usado literalmente como marco temporal de eventos clave —la huida a Egipto (Mt 2:14), la travesía del mar en la cuarta vigilia (Mt 14:25), el escape de Pablo (Hch 9:25)— y en fórmulas temporales como «cuarenta días y cuarenta noches» (Mt 4:2). También se emplea figuradamente para la era de tinieblas espirituales que cede ante el amanecer escatológico (Ro 13:12; 1 Ts 5:5-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72868, 'spa', 'Ciclo completo día-noche', 'Un período completo de veinticuatro horas que comprende tanto la noche como el día. La evidencia de 2 Corintios 11:25 muestra a Pablo describiendo su sufrimiento marítimo en términos temporales precisos, no simplemente ''mucho tiempo'', sino el ciclo entero de oscuridad y luz. Las traducciones multilingües mantienen la estructura compuesta, reflejando la precisión griega en la medición temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72869, 'spa', 'Noé (nombre propio)', 'Nombre propio del patriarca que, advertido por Dios del diluvio venidero, construyó el arca y preservó a su familia. En la enseñanza de Jesús, la generación de Noé ejemplifica la normalidad desprevenida antes del juicio repentino (Mt 24:37-38, Lc 17:26-27). Hebreos 11:7 lo presenta como héroe de la fe, y Pedro lo llama «pregonero de justicia» (2 P 2:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72872, 'spa', 'Espalda, región dorsal', 'La región dorsal del cuerpo, desde los hombros hasta la parte baja de la columna. En Romanos 11:10, Pablo emplea la imaginería de juicio del Salmo 69, donde las espaldas encorvadas significan sometimiento o carga. Los traductores en diversas lenguas mantienen la especificidad anatómica mientras comprenden el peso metafórico: un pueblo doblegado bajo las consecuencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72874, 'spa', 'Hospedar, recibir como huésped', 'Hospedar, recibir como huésped. Recibir, alojar y atender a alguien como huésped, brindando hospitalidad y refugio. Este es el sentido dominante en el NT, usado repetidamente en Hechos para el alojamiento de Pedro con Simón el curtidor (Hch 10:6, 18, 23, 32), Mnasón hospedando a Pablo en Jerusalén (Hch 21:16) y Publio atendiendo al grupo náufrago en Malta (Hch 28:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72877, 'spa', 'Sorprenderse, considerar extraño', 'Sorprenderse, considerar extraño. Sentir sorpresa, asombro, o considerar algo como extraño y ajeno. La lógica subyacente se conecta con ξένος: lo que es ''foráneo'' provoca sorpresa. En 1 Pe 4:4 los incrédulos ''se extrañan'' de que los cristianos ya no participen en sus excesos; en 1 Pe 4:12 se exhorta a los creyentes a no ''extrañarse'' de la prueba de fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72881, 'spa', 'Extraño, ajeno', 'Extraño, ajeno. Usado de manera adjetival o participial para describir la introducción de algo foráneo, desconocido o extraño ante una audiencia. En Hch 17:20 los atenienses dicen a Pablo ''traes cosas extrañas a nuestros oídos,'' usando ξενίζοντα como modificador. Este sentido conecta hospitalidad y sorpresa: lo que el forastero trae es en sí mismo extraño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72882, 'spa', 'Hospedar extranjeros', 'Extender hospitalidad recibiendo y cuidando a extranjeros o viajeros. En 1 Timoteo 5:10, esto se enumera entre las buenas obras de una viuda, exigiendo acción demostrada y no mera disposición. Las traducciones interlingüísticas enfatizan el acto concreto, reflejando una cultura donde abrir el hogar a desconocidos era arriesgado y virtuoso a la vez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72883, 'spa', 'Extranjero, forastero o desconocido', 'Extranjero, forastero o desconocido: alguien fuera de la comunidad local, ya sea un viajero que necesita hospitalidad, un residente extranjero o una persona desconocida. Este uso sustantivo dominante (11 apariciones) ancla la parábola de las ovejas y los cabritos: ''Fui forastero y me acogisteis'' (Mt 25:35, 38, 43, 44). El campo del alfarero se compra ''para sepultar a los extranjeros'' (Mt 27:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72886, 'spa', 'Anfitrión', 'Anfitrión: el que recibe y hospeda a los extranjeros, el polo recíproco de la relación huésped-anfitrión arraigada en la ξενία del griego clásico. En Ro 16:23, Pablo envía saludos de parte de ''Gayo, hospedador (ξένος) mío y de toda la iglesia''. El griego usa la misma palabra para ambos polos de la relación de hospitalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72887, 'spa', 'Extraño, ajeno o desconocido', 'Extraño, ajeno o desconocido: uso puramente adjetival que modifica conceptos abstractos en lugar de designar personas. En He 13:9, se advierte a los creyentes que no se dejen llevar por ''doctrinas extrañas'' (ξέναις διδαχαῖς), y en 1 P 4:12 no deben pensar que les sucede ''cosa extraña'' cuando llegan pruebas de fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72890, 'spa', 'Marchitarse o secarse (intransitivo/pasivo)', 'Marchitarse o secarse (intransitivo/pasivo): el sentido dominante con 14 apariciones, aplicado a plantas que se marchitan por el sol abrasador o por falta de raíz (Mt 13:6; Mr 4:6; Lc 8:6), la higuera maldecida por Jesús (Mt 21:19-20; Mr 11:20-21), una mano seca (Mr 3:1, 3), aguas que se secan (Ap 16:12) y la transitoriedad de la hierba (1 P 1:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72898, 'spa', 'Secar (transitivo/activo)', 'Secar (transitivo/activo): el sentido activo de causar que algo se seque o se marchite. En Santiago 1:11, el sol abrasador ''secó'' (ἐξήρανεν, aoristo activo) la planta, actuando como agente de desecación. Esta única aparición activa contrasta con el patrón pasivo dominante, poniendo énfasis en la fuerza externa que provoca el marchitamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72899, 'spa', 'Marchito, paralizado', 'Marchito, atrofiado, paralizado — describe una parte del cuerpo que se ha secado y perdido su función. Cinco ocurrencias se agrupan en relatos de sanidad: el hombre de la «mano seca» aparece en los tres evangelios sinópticos (Mt 12:10, Mr 3:3, Lc 6:6, 6:8), y Jn 5:3 enumera a quienes tenían miembros «secos» entre los enfermos de Betesda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72900, 'spa', 'Seco, árido', 'Seco, referido a tierra o material — lo opuesto a húmedo, verde o mojado. Tres ocurrencias emplean este sentido geográfico o material: Mt 23:15 («mar y tierra seca»), He 11:29 («tierra seca» en el cruce del Mar Rojo), y Lc 23:31 («si en el leño verde hacen estas cosas, ¿qué se hará en el seco?»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72905, 'spa', 'Árbol, especialmente en la fórmula teológica ''colgado en un madero'' aplicada a l', 'Árbol, especialmente en la fórmula teológica ''colgado en un madero'' aplicada a la crucifixión de Cristo. Las cinco referencias petrinas y paulinas (Hch 5:30, 10:39, 13:29; Gá 3:13; 1 P 2:24) usan esta palabra para invocar la maldición deuteronómica de Dt 21:22-23, reinterpretando la cruz como el madero maldito que trae salvación. El ''árbol de la vida'' de Apocalipsis (Ap 2:7; 22:2, 14) cierra los extremos del canon con el Edén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72906, 'spa', 'Palos o garrotes — armas de madera empuñadas a mano', 'Palos o garrotes — armas de madera empuñadas a mano. Las cinco apariciones se concentran en las narraciones sinópticas del arresto (Mt 26:47, 55; Mc 14:43, 48; Lc 22:52), donde Jesús confronta a la turba: ''¿Habéis salido con espadas y palos como contra un ladrón?'' El español ''palos'' capta la naturaleza tosca e improvisada de estas armas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72908, 'spa', 'Madera como material o mercancía — leña, madera de construcción o combustible', 'Madera como material o mercancía — leña, madera de construcción o combustible. Pablo la clasifica entre materiales de construcción que serán probados por fuego (1 Co 3:12), Apocalipsis la enumera entre bienes de comercio de lujo (Ap 18:12), y el proverbio de Jesús sobre la leña verde y seca (Lc 23:31) juega con la combustibilidad de la madera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72909, 'spa', 'Cepo — instrumento de madera para inmovilizar prisioneros, consistente en un arm', 'Cepo — instrumento de madera para inmovilizar prisioneros, consistente en un armazón que sujetaba los pies. Se usa únicamente en Hechos 16:24, donde el carcelero de Filipos aseguró los pies de Pablo y Silas en el cepo tras su arresto. El español ''cepo'' preserva la identidad específica del instrumento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72910, 'spa', 'Rapar o afeitar', 'Rapar, cortar el cabello al ras de la piel, ya sea por purificación ritual o como signo de vergüenza. Hechos 21:24 describe el cumplimiento del voto nazareo que exigía raparse la cabeza. Primera Corintios 11:5-6 emplea el rapado como argumento de reducción al absurdo sobre el cubrimiento de la cabeza: si una mujer no se cubre, que asuma la vergüenza de una cabeza rapada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72913, 'spa', 'artículo definido', 'El artículo definido básico que marca un sustantivo como conocido, específico, o mencionado previamente. Con más de 18,000 ocurrencias, es el uso fundamental en el Nuevo Testamento. Corresponde directamente a el/la/los/las en español, incluyendo formas contraídas como al (a + el) y del (de + el).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72932, 'spa', 'artículo conectivo o estructural', 'Enlaza cláusulas, marca transiciones, u organiza listas. Más visible en la genealogía de Mateo 1, donde el artículo repetido estructura la secuencia de nombres. A menudo se traduce de manera implícita en español o mediante conectores sutiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72935, 'spa', 'artículo dativo (objeto indirecto/locativo)', 'Marca objetos indirectos, ubicaciones, o instrumentos. El caso dativo griego comunica destinatario, lugar, o medio. En español se traduce típicamente con preposiciones: «al» (a + el), «en el», «con el», «del» (de + el cuando expresa procedencia).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72939, 'spa', 'artículo genitivo (posesivo/partitivo)', 'Marca posesión, fuente, o relaciones partitivas. El genitivo griego expresa pertenencia, origen, o parte de un todo. En español se traduce principalmente con «de» + artículo («del», «de la», «de los», «de las»), preservando la relación genitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72952, 'spa', 'sustantivizador o pronombre', 'Convierte adjetivos, participios, o frases preposicionales en frases sustantivas: «el que», «los que», «las cosas de». Esta función permite al griego crear expresiones nominales complejas sin sustantivo explícito. En español se traduce naturalmente con el artículo seguido del adjetivo o participio sustantivado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72971, 'spa', 'artículo comparativo', 'Artículo en construcciones comparativas que siguen adjetivos comparativos. Solo 14 ocurrencias en el Nuevo Testamento. Se traduce en español como «que el/la/los/las» o «de lo que», dependiendo del contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72979, 'spa', 'Octavo en secuencia', 'Octavo en una serie: la forma ordinal del número ocho. En Lc 1:59 marca el día prescrito para la circuncisión; en Hch 7:8 Abraham circuncidó a Isaac al octavo día. 2 Pedro 2:5 llama a Noé la ''octava persona'' (ὄγδοον... ἐφύλαξεν). Apocalipsis lo usa para un misterioso octavo rey (17:11) y la octava piedra de cimiento (21:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72980, 'spa', 'Peso, carga que estorba', 'Un estorbo o carga que impide el progreso, particularmente en la metáfora de la competencia atlética. Hebreos 12:1 insta a los creyentes a despojarse de ''todo peso'': cosas que, aunque no sean pecaminosas en sí mismas, obstaculizan la carrera hacia Cristo. La imagen proviene de la cultura atlética griega donde los corredores eliminaban toda carga innecesaria antes de competir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72981, 'spa', 'Este, estos (pronombre demostrativo)', 'Este, estos (pronombre demostrativo). Pronombre demostrativo de cercanía que significa ''este, esta, estos, estas,'' usado para señalar lo que está presente, lo recién mencionado o lo que va a declararse. Aparece en todos los géneros (masculino, femenino, neutro) y números (singular, plural) con función deíctica uniforme. Predomina en la fórmula profética de Apocalipsis — ''Esto dice el que tiene las siete estrellas'' (Ap 2:1, 8, 12, 18; 3:1, 7, 14) — y en declaraciones proféticas como la de Ágabo (Hch 21:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72984, 'spa', 'Viajero, caminante', 'Quien viaja por un camino o realiza una travesía. En la parábola del buen samaritano (Lucas 10:33), este participio presenta al samaritano en movimiento, ''viajando'' o ''yendo de camino'', cuando encuentra al hombre herido. El detalle resalta que, a pesar de ir en ruta con sus propios asuntos, interrumpe su viaje para prestar auxilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72985, 'spa', 'Guiar, conducir', 'Guiar o conducir a alguien por un camino, física o metafóricamente. La raíz ὁδός (camino) le confiere un sentido fuertemente direccional: no mera influencia, sino conducción activa hacia un objetivo. Jesús advierte que guías ciegos conducen a un hoyo (Mt 15:14; Lc 6:39), y en Jn 16:13 el Espíritu guiará ''a toda la verdad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72986, 'spa', 'Guía, conductor', 'Guía o conductor, quien dirige a otros por un camino físico o moral. Las cinco apariciones neotestamentarias portan fuertes matices metafóricos. La acusación de Jesús contra los ''guías ciegos'' (ὁδηγοὶ τυφλοί, Mt 23:16, 24) desenmascara a líderes que extravían. En Hch 1:16, Judas sirvió de ὁδηγός para los captores de Jesús, una sombría inversión del rol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72987, 'spa', 'Viajar, ir de camino', 'Viajar o hacer un recorrido, especialmente a pie hacia un destino. En Hechos 10:9, este verbo describe a los mensajeros de Cornelio dirigiéndose a Jope. El término enfatiza el viaje en curso —estaban ''viajando'', no simplemente ''fueron''—, creando tensión narrativa mientras la visión de Pedro ocurre justo cuando ellos se aproximan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72989, 'spa', 'camino, senda (general)', 'Un camino, ruta o senda en sentido tanto literal como figurado, abarcando la gran mayoría de las apariciones (79) en formas singulares. Los usos literales incluyen el camino a Egipto (Mt 2:12), ''el camino del mar'' (Mt 4:15) y la senda del sembrador (Mt 13:4). Los usos figurados incluyen ''el camino del Señor'' (Mt 3:3), ''yo soy el camino'' (Jn 14:6) y el camino ancho frente al estrecho (Mt 7:13-14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72990, 'spa', 'caminos (plural)', 'Formas plurales (ὁδοί, ὁδούς) que designan múltiples caminos o cursos de conducta — carreteras, encrucijadas o los múltiples caminos de Dios. Mt 22:9-10 envía siervos a ''los caminos'' para invitar a los convidados; Lc 3:5 endereza ''los caminos torcidos''; Ro 11:33 se maravilla de los inescrutables ''caminos'' de Dios. Las catorce apariciones en plural se distribuyen entre lo literal y lo figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72991, 'spa', 'el Camino (movimiento cristiano)', 'El título técnico ''el Camino'' (ἡ Ὁδός) para el movimiento cristiano primitivo, concentrado en Hechos. Saulo persigue a ''los del Camino'' (Hch 9:2); Apolos es instruido con más exactitud en ''el Camino del Señor'' (Hch 18:25); los plateros provocan un disturbio por ''el Camino'' (Hch 19:23). Ocho apariciones se agrupan en Hch 9-24, reflejando el vocabulario distintivo de Lucas para el cristianismo más temprano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72997, 'spa', 'Diente', 'Diente: usado casi exclusivamente en la fórmula neotestamentaria ''crujir de dientes'' para la angustia escatológica (Mt 8:12; 13:42, 50; 25:30; Lc 13:28), más una vez en ''diente por diente'' (Mt 5:38). No presenta subdivisión semántica alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73000, 'spa', 'Sufrir, angustiarse', 'Experimentar dolor, angustia o tormento intenso, ya sea físico o emocional. El hombre rico en el Hades lo usa para la agonía corporal en las llamas (Lc 16:24-25), María para la angustia de un hijo perdido (Lc 2:48), y los ancianos de Éfeso para el dolor ante la separación de Pablo (Hch 20:38). El verbo griego abarca ambos registros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73004, 'spa', 'Emitir hedor', 'Despedir un olor, aquí específicamente un hedor fétido por descomposición. Juan 11:39 registra la objeción de Marta: tras cuatro días, el cuerpo de Lázaro «hiede». La crudeza del verbo subraya la realidad de la muerte, haciendo que la orden de Cristo de quitar la piedra sea un acto de fe contra toda evidencia sensorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73005, 'spa', 'De donde, desde donde (espacial/origen)', 'De donde, desde donde (espacial/origen): adverbio relativo de origen espacial que indica el lugar o la fuente de donde alguien o algo proviene. El espíritu inmundo regresa a la casa ''de donde'' salió (Mt 12:44; Lc 11:24); el amo severo cosecha ''de donde'' no sembró (Mt 25:24, 26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73006, 'spa', 'Por lo cual, por esa razón (inferencial)', 'Por lo cual, por esa razón (inferencial): conjunción inferencial que significa ''por lo tanto'', ''de ahí'' o ''por lo cual'', representando una extensión semántica del origen espacial al fundamento lógico. Concentrado en Hebreos (2:17; 3:1; 7:25; 8:3), introduce conclusiones teológicas de gran peso: ''Por lo cual debía ser hecho semejante a sus hermanos en todo'' (He 2:17). Pablo lo usa de forma similar en Hch 26:19 para una conclusión derivada de la visión en el camino a Damasco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73010, 'spa', 'Lienzos funerarios', 'Tiras o piezas de lino para envolver un cuerpo en la sepultura. La forma diminutiva (de ὀθόνη) indica piezas pequenas, no una sabana unica como σινδών. Todo uso neotestamentario se vincula a la sepultura de Jesus (Juan 19:40) y al hallazgo de los lienzos en la tumba vacia como evidencia de la resurreccion (Lucas 24:12; Juan 20:5-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73011, 'spa', 'Miembros del hogar', 'Personas que pertenecen a una casa, familia o círculo doméstico, unidas por parentesco o asociación. Gálatas 6:10 lo aplica a los creyentes como «familia de la fe». Efesios 2:19 declara a los gentiles miembros de la familia de Dios. Primera Timoteo 5:8 habla de proveer para los propios. El griego οἰκεῖος, derivado de οἶκος (casa), enfatiza pertenencia y obligación mutua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73012, 'spa', 'Siervo domestico', 'Siervo o esclavo que sirve dentro del ambito intimo del hogar, no en campos ni en servicio publico. Derivado de οἶκος (casa), enfatiza la pertenencia a una familia. En Romanos 14:4, el οἰκέτης pertenece a su propio amo. Primera de Pedro 2:18 exhorta a estos siervos domesticos a la obediencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73013, 'spa', 'Habitar, morar', 'Residir en, habitar o hacer morada en un lugar o persona. El sentido literal de habitación física subyace al término, pero en el NT destaca el uso metafórico paulino para la morada espiritual. En Romanos 7:17-20, el pecado se personifica como ocupante que «habita en» la carne. Romanos 8:9-11 responde con el Espíritu de Dios habitando en los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73017, 'spa', 'Celda o aposento', 'Un aposento o lugar de habitación, aquí específicamente una celda de prisión. Hechos 12:7 narra el encarcelamiento de Pedro: una luz brilla «en la celda» donde duerme encadenado. Aunque el término griego tiene significados más amplios (dormitorio, almacén), el contexto de cadenas y guardias lo define como lugar de detención, escenario de una dramática liberación angélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73019, 'spa', 'casa, vivienda (edificio)', 'Estructura física —casa, edificio o vivienda—, sentido dominante que abarca la gran mayoría de las apariciones. Jesús enseña sobre la casa edificada sobre roca frente a la arena (Mt 7:24-26), y sus seguidores se reúnen en casas para comer y recibir instrucción (Mt 5:15; Mc 2:15). El español «casa» traduce este sentido de manera directa como estructura material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73022, 'spa', 'hogar (familia, miembros)', 'Extensión metonímica del edificio a sus habitantes: «hogar» o «familia», es decir, las personas que conforman una unidad doméstica. Pablo elogia «la familia de Estéfanas» (1 Co 16:15) y envía saludos de parte de «los de la casa de César» (Fil 4:22). El desplazamiento de estructura a personas es sutil en muchas lenguas —en español «casa» cubre ambos sentidos—, pero el contexto indica claramente cuándo se refiere a personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73025, 'spa', 'Gobernar el hogar', 'Ejercer autoridad y supervisión como cabeza de un hogar, administrando los asuntos domésticos. 1 Timoteo 5:14 enumera la administración del hogar entre los deberes de las viudas jóvenes que se casan, enfatizando una mayordomía responsable. El verbo implica más que tareas del hogar: denota liderazgo y gobernanza integral del bienestar espiritual y material de la casa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73026, 'spa', 'Dueño o amo de una casa que ejerce autoridad sobre los asuntos domésticos', 'Dueño o amo de una casa que ejerce autoridad sobre los asuntos domésticos. Jesús emplea esta figura en parábolas: el dueño de casa que contrata obreros para la viña (Mt 20:1), el amo que espera vigilancia (Mr 13:35; Lc 12:39), el escriba como dueño de casa (Mt 13:52). Es un concepto unificado que designa al jefe del hogar con plena autoridad sobre su administración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73028, 'spa', 'Construir o edificar fisicamente', 'Construir o edificar fisicamente. Erigir o construir una estructura fisica: casa, templo, torre, tumba o muro de vina. Es el sentido literal y fundacional, prominente en las parabolas de Jesus: los constructores sabio e insensato (Mt 7:24, 26), la torre del dueno de la vina (Mt 21:33) y los fariseos que edifican sepulcros a los profetas (Mt 23:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73029, 'spa', 'Edificar espiritualmente', 'Edificar espiritualmente. Fortalecer, animar o edificar a una persona o comunidad en la fe: el sentido metaforico que se volvio central en la teologia paulina. En 1 Corintios 8:1, el conocimiento envanece pero el amor ''edifica'' (οἰκοδομεῖ). Hechos 9:31 describe a la iglesia primitiva siendo ''edificada'' en paz. El espanol distingue este sentido con ''edifica'' y el reflexivo ''edificaos'' (Jud 1:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73030, 'spa', 'Edificar (sentido general o contextual)', 'Edificar (sentido general o contextual). Edificar en un sentido general o contextualmente ambiguo que puede abarcar tanto la construccion literal como la edificacion figurada, incluyendo la reconstruccion de lo destruido. La sentencia de Jesus ''destruid este templo y en tres dias lo levantare'' (Mt 26:61; Mr 15:29) opera en ambos planos simultaneamente. Lucas 14:28 lo usa para calcular el costo de edificar una torre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73035, 'spa', 'Constructor (sustantivo de agente)', 'Constructor (sustantivo de agente). Quien construye: sustantivo de agente derivado del participio, usado sustantivamente para designar constructores o edificadores. Las cinco apariciones se agrupan en torno a la misma cita del Salmo 118:22: ''la piedra que desecharon los constructores ha venido a ser la piedra angular'' (Mt 21:42; Mr 12:10; Lc 20:17; Hch 4:11; 1 P 2:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73051, 'spa', 'Proceso abstracto de fortalecimiento y edificación espiritual o comunitaria', 'Proceso abstracto de fortalecimiento y edificación espiritual o comunitaria. El español ''edificación'' preserva la metáfora arquitectónica incrustada en la palabra, revelando cuán naturalmente la imagen de construir un edificio se transfiere al fortalecimiento de una comunidad de fe. Pablo despliega este sentido extensamente en su correspondencia corintia: la profecía edifica (1 Co 14:3), todo debe hacerse para edificación (1 Co 14:26), y los creyentes deben procurar lo que contribuye a la edificación mutua (Ro 14:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73053, 'spa', 'Edificio o estructura física concreta', 'Edificio o estructura física concreta. El discurso apocalíptico sinóptico se abre con los discípulos admirando los imponentes edificios del Templo (Mt 24:1; Mc 13:1), solo para que Jesús profetice que no quedará piedra sobre piedra (Mc 13:2). Pablo llama a la iglesia corintia ''edificio de Dios'' (1 Co 3:9) y habla de un ''edificio de Dios, una casa no hecha de manos'' que espera a los creyentes en el cielo (2 Co 5:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73057, 'spa', 'Administrar como mayordomo', 'Actuar como mayordomo o administrador, gestionando recursos en nombre de un propietario. Lucas 16:2 retrata el momento crítico en que al mayordomo se le dice que «ya no podrá administrar»: su autoridad está siendo revocada. El término captura la esencia de la responsabilidad delegada: administrar lo ajeno, tema clave en la enseñanza de Jesús sobre la fidelidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73058, 'spa', 'Administración, mayordomía', 'La responsabilidad y autoridad para gestionar, administrar o supervisar una casa, hacienda o plan divino. En Lucas 16:2-4, el mayordomo infiel enfrenta la pérdida de su οἰκονομία —su cargo de administración— y debe ingeniárselas para asegurar su futuro, enraizando el término en la vida económica cotidiana. Pablo lo extiende cósmicamente: él mismo posee una ''mayordomía'' del evangelio que le fue encomendada (1 Co 9:17; Col 1:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73062, 'spa', 'Mayordomo, administrador', 'Mayordomo, administrador. Persona a quien se confía la gestión de una casa, hacienda o conjunto de recursos en nombre de un propietario; un mayordomo o administrador con responsabilidad fiduciaria. Abarca el uso parabólico (el mayordomo fiel de Lc 12:42, el mayordomo injusto de Lc 16:1-8), la mayordomía espiritual (administradores de los misterios de Dios, 1 Co 4:1-2; administrador de Dios, Tit 1:7; administradores de la gracia, 1 Pe 4:10) y el cargo cívico (Erasto, tesorero de la ciudad, Ro 16:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73069, 'spa', 'casa, morada', 'Edificio físico, vivienda o estructura: desde residencias privadas (Mt 9:6-7, «vete a tu casa») hasta el templo de Jerusalén llamado casa de Dios (Mt 21:13, «mi casa será llamada casa de oración»). Abarca espacios domésticos, habitaciones y recintos sagrados. Las traducciones multilingües (spa: casa, fra: maison, deu: Haus) lo tratan uniformemente como el sentido primario y no marcado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73073, 'spa', 'familia, hogar', 'El hogar o la familia como unidad social, extendiendo el sentido más allá de las paredes hacia las personas que las habitan. Se usa para la administración del hogar como requisito del liderazgo eclesial (1 Ti 3:12) y para quienes «trastornan casas enteras» con falsas enseñanzas (Tit 1:11). La metonimia del edificio a las personas refleja la misma extensión del hebreo בַּיִת (H1004).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73075, 'spa', 'El mundo habitado y civilizado', 'El mundo habitado y civilizado: la esfera de habitación humana y orden político. En Lucas-Hechos frecuentemente designa el mundo imperial romano: Augusto decreta un censo de ''toda la οἰκουμένη'' (Lc 2:1), y Agabo predice hambruna sobre el mismo ámbito (Hch 11:28). Jesús la usa escatológicamente para el escenario donde el evangelio debe llegar antes del fin (Mt 24:14) y donde la tribulación probará a todos los que habitan en ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73078, 'spa', 'Dedicada al hogar', 'Consagrada al hogar y al trabajo doméstico, describiendo a mujeres dedicadas a la administración de la casa. Tito 2:5 incluye esta cualidad entre las virtudes de las esposas jóvenes, reflejando el valor cultural de la mayordomía del hogar. Se traduce como «hacendosas» o «dedicadas al hogar», reconociendo que la administración doméstica antigua implicaba responsabilidad económica y social considerable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73080, 'spa', 'Compasion misericordiosa', 'Compasion o misericordia: sentimientos viscerales de piedad que mueven a actuar con clemencia. El plural (οἰκτιρμοί) sugiere plenitud compasiva. En Romanos 12:1, Pablo fundamenta su exhortacion etica en ''las compasiones de Dios''. Segunda de Corintios 1:3 nombra a Dios ''Padre de misericordias''. Colosenses 3:12 manda revestirse de entranas de misericordia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73081, 'spa', 'Compasivo, misericordioso', 'Misericordioso, compasivo; caracterizado por una piedad activa y bondad hacia quienes sufren. Lucas 6:36 (expresado dos veces) ordena imitar la misericordia del Padre. Santiago 5:11 atribuye esta cualidad al Señor que vindica a Job. El griego οἰκτίρμων enfatiza una compasión visceral, nacida del sentir profundo ante el sufrimiento ajeno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73083, 'spa', 'Vino', 'Vino. Jugo de uva fermentado, la principal bebida alcoholica de la antiguedad: el vino como bebida fisica empleada en comidas, celebraciones y ofrendas religiosas. Aparece en contextos literales como las bodas de Cana (Jn 2:3), la parabola de los odres (Mt 9:17; Mr 2:22) y el vinagre ofrecido en la crucifixion (Mt 27:34). En Apocalipsis, el vino se asocia tambien con la copa de la ira de Dios, ampliando su simbolismo mas alla del ambito cotidiano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73088, 'spa', 'Embriaguez habitual por vino', 'Embriaguez habitual o consumo excesivo de vino. En 1 Pedro 4:3 este término figura en un catálogo de vicios gentiles que los creyentes han dejado atrás. La palabra denota específicamente la intoxicación producida por el vino, como parte de un estilo de vida marcado por el exceso sensual y la falta de dominio propio. Los lectores de Pedro habían renunciado a tales prácticas al convertirse, abrazando la sobriedad y el autocontrol piadoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73089, 'spa', 'Suponer, opinar', 'Pensar, suponer o imaginar; formarse una opinión o estimación subjetiva. Juan 21:25 usa οἴομαι para la suposición del evangelista sobre la capacidad del mundo para contener los libros. Filipenses 1:17 habla de quienes suponen erróneamente sobre la aflicción de Pablo. Santiago 1:7 advierte al indeciso que no suponga que recibirá algo. El término señala un juicio personal, no un conocimiento seguro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73090, 'spa', 'Pronombre relativo cualitativo que significa ''tal como'', ''de qué clase'' o ''de qu', 'Pronombre relativo cualitativo que significa ''tal como'', ''de qué clase'' o ''de qué tipo'', usado para describir el carácter o la naturaleza de algo en vez de su cantidad o identidad. Se emplea en advertencias escatológicas para marcar eventos como sin precedentes en su cualidad: ''tribulación cual no ha ocurrido desde el principio de la creación'' (Mr 13:19; Mt 24:21). También se usa en la Transfiguración para expresar la blancura sobrenatural e incomparable de las vestiduras de Jesús (Mr 9:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73099, 'spa', 'Vacilar o tardar', 'Vacilar o demorar en actuar, a menudo por renuencia u otros factores que obstaculizan. Hechos 9:38 registra la súplica enviada a Pedro: «No tardes en venir a nosotros». La comunidad de Jope, habiendo perdido a la amada Tabita, convoca a Pedro con urgencia, y su imperativo está cargado de esperanza de que una acción inmediata pudiera aún traer restauración. El verbo capta el temor de que cualquier vacilación significara una oportunidad perdida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73100, 'spa', 'Perezoso, remiso', 'Perezoso, negligente, vacilante o molesto; caracterizado por la reluctancia a actuar o comprometerse. Mateo 25:26 condena al siervo ὀκνηρός que no invirtió su talento. Romanos 12:11 advierte contra la pereza en el celo. Filipenses 3:1 lo usa de forma distinta: las instrucciones repetidas de Pablo no son «molestas». El griego ὀκνηρός, de ὄκνος (vacilación), abarca la pereza moral y la desgana práctica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73101, 'spa', 'De ocho días', 'Que tiene ocho días de edad, describiendo específicamente la edad a la cual los varones judíos eran circuncidados conforme a la Ley. Filipenses 3:5 emplea este término en la autobiografía de Pablo para establecer su auténtica identidad judía de nacimiento: «circuncidado al octavo día» (literalmente, «siendo de ocho días»). Este detalle demuestra que nació dentro del pacto, no fue un converso tardío, subrayando la legitimidad de su herencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73102, 'spa', 'Ocho (numeral cardinal)', 'Ocho (numeral cardinal). El número cardinal ocho, usado para contar días (Lc 2:21, circuncisión al octavo día; Lc 9:28, unos ocho días después; Jn 20:26, después de ocho días), años (Lc 13:11, 16, atada durante dieciocho años), personas (1 Pe 3:20; 2 Pe 2:5, ocho almas en el arca) y víctimas (Lc 13:4, los dieciocho sobre quienes cayó la torre).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73103, 'spa', 'Destruccion catastrofica', 'Destruccion total o ruina como consecuencia del juicio divino o catastrofe moral. En 1 Corintios 5:5, es la ruina fisica de la carne para salvar el espiritu. En 1 Tesalonicenses 5:3, el desastre subito sobre los confiados. En 2 Tesalonicenses 1:9, ''destruccion eterna'' designa la separacion escatologica de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73104, 'spa', 'De poca fe', 'Que posee fe insuficiente o vacilante, usado por Jesús como reproche a discípulos cuya confianza en Dios falla bajo presión. El compuesto (ὀλίγο- ''poco'' + πιστός ''fiel'') aparece exclusivamente en Mateo y el paralelo de Lucas 12:28, siempre en labios de Jesús, cubriendo ansiedad, temor y torpeza espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73107, 'spa', 'Poco, escaso, pequeno en numero', 'Poco, escaso, pequeno en numero. Pequeno en cantidad, numero o extension; pocos. Se usa atributiva y predicativamente de personas (Mt 7:14; 22:14 ''muchos son llamados, pocos elegidos''), cosas (Mt 25:21 ''fiel sobre poco''), tiempo (Ap 12:12 ''poco tiempo'') y grado (Mr 1:19 ''un poco mas adelante''). El espanol ''poco/pequeno'', el frances ''peu'' y el aleman ''wenig'' convergen en la idea de escasez cuantitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73110, 'spa', 'Apenas, con dificultad', 'Apenas, con dificultad. Uso adverbial que significa ''apenas, escasamente, con dificultad''. Se encuentra en 2 Pedro 2:18, describiendo a quienes ''apenas'' escapan de los que viven en el error. El espanol ''apenas'' distingue de modo unico este sentido adverbial del adjetival, mientras que el frances y el aleman mantienen la misma raiz (''peu'', ''wenig''), dependiendo del contexto para el cambio de sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73115, 'spa', 'Pusilánime o desanimado', 'Aquellos que son pusilánimes, desalentados o débiles de espíritu. En 1 Tesalonicenses 5:14 se identifica a este grupo como necesitado de cuidado pastoral específico mediante el aliento. Pablo los distingue de los indisciplinados (que necesitan amonestación) y de los débiles (que necesitan apoyo): son creyentes cuyo valor desfallece ante la prueba y que requieren palabras de fortalecimiento para perseverar. El término significa literalmente «de alma pequeña».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73116, 'spa', 'Menospreciar o desdeñar', 'Estimar ligeramente o considerar insignificante, particularmente en relación con la disciplina divina. Hebreos 12:5 advierte contra «menospreciar la disciplina del Señor», citando Proverbios 3:11. El verbo capta una actitud desdeñosa que no logra reconocer la corrección como expresión del amor paternal de Dios. «Hacer poco caso» de la disciplina es pasar por alto su propósito formativo y redentor, tratándola como simple inconveniencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73117, 'spa', 'Destructor del juicio divino', 'Agente de destrucción, específicamente el ángel destructor que ejecutaba el juicio divino. 1 Corintios 10:10 recuerda la rebelión de Israel en el desierto, donde los murmuradores «fueron destruidos por el Destructor», aludiendo a Números 16-17 y la rebelión de Coré. Pablo emplea este precedente solemne para advertir a los corintios: el juicio divino a través del Destructor sigue siendo una posibilidad real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73118, 'spa', 'Destructor de la Pascua', 'El que destruye, específicamente el ángel destructor de la Pascua que dio muerte a los primogénitos de Egipto. Hebreos 11:28 relata la obediencia de Moisés al celebrar la Pascua por fe: la sangre en los dinteles protegió a Israel «para que el Destructor no los tocara». Este agente de juicio es personal y activo, pero contenido por la señal del pacto: la sangre que marcaba a los protegidos por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73119, 'spa', 'Holocausto', 'Holocausto u ofrenda quemada: sacrificio del Antiguo Testamento en el que el animal entero se consumía por el fuego sobre el altar como ofrenda a Dios. Marcos 12:33 contrasta el amor con todos los holocaustos. Hebreos 10:6, 8 (citando el Salmo 40) declara el desagrado de Dios ante los meros holocaustos rituales, señalando al sacrificio superior de Cristo. El griego ὁλοκαύτωμα significa «completamente quemado», de ὅλος (entero) y καίω (quemar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73120, 'spa', 'Sanidad corporal completa', 'Plenitud o integridad completa, particularmente salud corporal perfecta. Hechos 3:16 emplea este término para describir la sanación del hombre que era cojo: la fe en Jesús le dio «perfecta salud» (literalmente «plenitud»). El término subraya la totalidad —cada parte sana y funcional—, haciendo el milagro innegable. Pedro señala esta restauración visible y completa como prueba del poder y la vindicación de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73122, 'spa', 'Lamentarse a gritos', 'Dar alaridos o clamar a voces, típicamente en lamentación o angustia. Santiago 5:1 ordena a los ricos opresores «llorar y dar alaridos» por las miserias venideras, un llamado al duelo sonoro propio del juicio inminente. Las asociaciones clásicas del verbo con gritos rituales (a menudo dirigidos a deidades) añaden gravedad: no se trata de arrepentimiento privado sino de catástrofe pública.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73123, 'spa', 'todo, entero', 'Sentido primario que cubre la inmensa mayoría de los usos: todo, entero, la totalidad sin excepción. Se aplica a regiones geográficas («toda Galilea», Mt 4:23), grupos («toda la ciudad», Mt 8:34), el cuerpo humano («todo tu cuerpo», Mt 5:29) y totalidades abstractas («toda la ley», Gá 5:14). Todas las lenguas convergen: spa «toda/todo/entero», fra «tout», deu «ganz».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73128, 'spa', 'completo, íntegro', 'Matiz cualitativo que significa completo, íntegro o ininterrumpido, no solo totalidad cuantitativa sino la idea de algo que permanece intacto a lo largo de toda su extensión o duración. En Hch 11:26 Bernabé y Saulo se reúnen con la iglesia «un año entero» (subrayando la continuidad sin interrupción), y en Hch 28:30 Pablo permanece «dos años enteros» (enfatizando la plenitud del período).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73131, 'spa', 'completamente (adverbial)', 'Uso adverbial en que ὅλος funciona como «completamente, del todo, enteramente», modificando la manera de una acción en lugar de un sustantivo. En Jn 7:23 Jesús argumenta de menor a mayor: si la circuncisión se practica en sábado, ¿por qué objetar hacer a un hombre «del todo» sano? En Jn 9:34 los fariseos replican que aquel hombre nació «enteramente» en pecados.');